/**
 * Validates the PAC generated by the companion and installs it. The extension
 * never installs a PAC it has not validated, and never clears an installed PAC
 * on failure: a stale PAC still fails closed through the companion proxy.
 */

import { BLOCK_PROXY, PAC_BODY, PAC_PREFIX } from "../lib/policy.js";

const PROXY_PATTERN = /^SOCKS5 127\.0\.0\.1:([0-9]{1,5})$/;
const RULE_KEYS = ["host", "proxy"];

export class RoutingError extends Error {
  readonly code: string;

  constructor(code: string, message: string) {
    super(message);
    this.name = "RoutingError";
    this.code = code;
  }
}

export interface PacRule {
  readonly host: string;
  readonly proxy: string;
}

export interface ValidatedPac {
  readonly rules: readonly PacRule[];
  /** Loopback proxy the PAC routes to, or null when every rule blocks. */
  readonly proxyAddr: string | null;
  readonly routeCount: number;
  readonly blockCount: number;
}

export function validatePac(pac: string): ValidatedPac {
  if (!pac.startsWith(PAC_PREFIX)) {
    throw new RoutingError("bad_pac", "PAC header is missing");
  }
  const rest = pac.slice(PAC_PREFIX.length);
  const end = rest.indexOf(";\n");
  if (end < 0) {
    throw new RoutingError("bad_pac", "PAC rule table is not terminated");
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rest.slice(0, end));
  } catch {
    throw new RoutingError("bad_pac", "PAC rule table is not valid JSON");
  }
  if (!Array.isArray(parsed)) {
    throw new RoutingError("bad_pac", "PAC rule table is not an array");
  }

  const rules: PacRule[] = [];
  const routeProxies = new Set<string>();
  let blockCount = 0;
  for (const [index, value] of parsed.entries()) {
    const rule = parseRule(value, index);
    if (rule.proxy === BLOCK_PROXY) {
      blockCount += 1;
    } else {
      routeProxies.add(rule.proxy);
    }
    rules.push(rule);
  }

  if (routeProxies.size > 1) {
    throw new RoutingError("bad_pac", "PAC routes to more than one proxy");
  }
  const proxyAddr = routeProxies.size === 1 ? routeAddr([...routeProxies][0] ?? "") : null;

  if (!pac.endsWith(`;\n${PAC_BODY}`)) {
    throw new RoutingError("bad_pac", "PAC interpreter was modified");
  }

  return {
    rules,
    proxyAddr,
    routeCount: rules.length - blockCount,
    blockCount,
  };
}

function parseRule(value: unknown, index: number): PacRule {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new RoutingError("bad_pac", `PAC rule ${index} is not an object`);
  }
  const record = value as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (!RULE_KEYS.includes(key)) {
      throw new RoutingError("bad_pac", `PAC rule ${index} has an unknown field`);
    }
  }
  const host = record.host;
  const proxy = record.proxy;
  if (typeof host !== "string" || host.length === 0 || host.length > 260) {
    throw new RoutingError("bad_pac", `PAC rule ${index} has an invalid host`);
  }
  if (host.includes("DIRECT") || /[\s/;]/.test(host)) {
    throw new RoutingError("bad_pac", `PAC rule ${index} has an unsafe host`);
  }
  if (typeof proxy !== "string" || proxy.length === 0) {
    throw new RoutingError("bad_pac", `PAC rule ${index} has an invalid proxy`);
  }
  if (proxy !== BLOCK_PROXY) {
    routeAddr(proxy);
  }
  return { host, proxy };
}

function routeAddr(proxy: string): string {
  const match = PROXY_PATTERN.exec(proxy);
  const portText = match?.[1];
  if (portText === undefined) {
    throw new RoutingError("bad_pac", "PAC proxy is not loopback SOCKS5");
  }
  const port = Number(portText);
  if (port < 1 || port > 65535 || port === 9) {
    throw new RoutingError("bad_pac", `PAC proxy port ${portText} is unusable`);
  }
  return `127.0.0.1:${portText}`;
}

export interface ProxySnapshot {
  readonly levelOfControl: string;
  readonly mode: unknown;
  readonly pac: unknown;
  readonly mandatory: unknown;
}

/** The installed proxy must be exactly our mandatory PAC, or routing is not ours. */
export function pacSatisfied(snapshot: ProxySnapshot, pac: string): boolean {
  return (
    snapshot.levelOfControl === "controlled_by_this_extension" &&
    snapshot.mode === "pac_script" &&
    snapshot.pac === pac &&
    snapshot.mandatory === true
  );
}

export function readPacSetting(): Promise<ProxySnapshot> {
  return new Promise<ProxySnapshot>((resolve, reject) => {
    chrome.proxy.settings.get({ incognito: false }, (details) => {
      const err = chrome.runtime.lastError;
      if (err) {
        reject(new RoutingError("proxy_read_failed", err.message ?? "proxy settings could not be read"));
        return;
      }
      const value = (details.value ?? {}) as {
        mode?: unknown;
        pacScript?: { data?: unknown; mandatory?: unknown };
      };
      resolve({
        levelOfControl: details.levelOfControl,
        mode: value.mode,
        pac: value.pacScript?.data,
        mandatory: value.pacScript?.mandatory,
      });
    });
  });
}

/**
 * Validates, installs, and reads back the PAC as a mandatory regular-scope
 * proxy. A read-back mismatch means another extension or an enterprise policy
 * owns the setting, so routing is not actually active.
 */
export async function installPac(pac: string): Promise<ValidatedPac> {
  const validated = validatePac(pac);
  await new Promise<void>((resolve, reject) => {
    chrome.proxy.settings.set(
      {
        value: {
          mode: "pac_script",
          pacScript: { data: pac, mandatory: true },
        },
        scope: "regular",
      },
      () => {
        const err = chrome.runtime.lastError;
        if (err) {
          reject(new RoutingError("proxy_set_failed", err.message ?? "proxy settings failed"));
          return;
        }
        resolve();
      },
    );
  });

  const snapshot = await readPacSetting();
  if (!pacSatisfied(snapshot, pac)) {
    throw new RoutingError("proxy_override", "proxy settings did not stay under extension control");
  }
  return validated;
}
